<?php use LipePool\Security\Csrf; use LipePool\Support\View; ?>
<section class="page-heading container"><p class="eyebrow">Minha conta</p><h1>Olá, <?= View::escape($_SESSION['user']['name'] ?? '') ?></h1><p class="lead">Acompanhe suas solicitações e seus atendimentos.</p><a class="button button-primary" href="/agendar">Solicitar agendamento</a></section>
<section class="container section"><div class="section-heading-row"><h2>Meus agendamentos</h2><span class="muted"><?= count($appointments) ?> registro(s)</span></div>
<?php if (!$appointments): ?><div class="empty-state"><h3>Ainda não há agendamentos</h3><p>Quando você solicitar um atendimento, ele aparecerá nesta lista.</p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Serviço</th><th>Data</th><th>Horário</th><th>Status</th><th>Ação</th></tr></thead><tbody>
<?php foreach ($appointments as $appointment): ?><tr><td><?= View::escape($appointment['service_name']) ?></td><td><?= View::escape(date('d/m/Y', strtotime($appointment['appointment_date']))) ?></td><td><?= View::escape(substr($appointment['appointment_time'], 0, 5)) ?></td><td><span class="status status-<?= View::escape($appointment['status']) ?>"><?= View::escape(['requested'=>'Solicitado','completed'=>'Concluído','cancelled'=>'Cancelado'][$appointment['status']] ?? $appointment['status']) ?></span><?php if ($appointment['notes']): ?><p class="muted table-note"><?= nl2br(View::escape($appointment['notes'])) ?></p><?php endif; ?></td><td><?php if ($appointment['status'] === 'requested'): ?><form method="post" action="/conta/agendamentos/<?= (int) $appointment['id'] ?>/cancelar"><input type="hidden" name="_csrf" value="<?= View::escape(Csrf::token()) ?>"><button class="button button-danger button-small" type="submit">Cancelar</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?></section>
